def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 99:
        return 'D'
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c_total = 0
    opp_c_5 = 0
    opp_c_10 = 0
    for i in range(n):
        o = history[i][1]
        if o == 'C':
            opp_c_total += 1
            if i >= n - 5:
                opp_c_5 += 1
            if i >= n - 10:
                opp_c_10 += 1
    opp_d_total = n - opp_c_total

    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    soft = 0
    hard = 0
    forgive = 0
    punish = 0
    for i in range(n - 1):
        if history[i][1] == 'D':
            if history[i + 1][1] == 'C':
                forgive += 1
            else:
                punish += 1
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'C':
                soft += 1
            elif history[i + 1][1] == 'D':
                hard += 1

    recent_my_d = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    if opp_c_total == 0:
        return 'D'

    if opp_c_total * 5 <= n and n >= 8:
        if opp_last == 'D' and same_count >= 5 and forgive > 0 and rng.random() < 0.10:
            return 'C'
        return 'D'

    if opp_last == 'C' and opp_c_total >= n - 6:
        soft_edge = soft - hard
        if soft_edge > 0:
            if hard == 0 and soft >= 4:
                return 'D'
            p = 0.35 + 0.12 * min(soft, 4) - 0.30 * min(hard, 1)
            if opp_d_total == 0:
                p += 0.30
            if my_last == 'D':
                p += 0.15
            if n >= 85:
                p += 0.20
            if recent_my_d >= 3:
                p -= 0.20
            if p > 0 and rng.random() < min(0.95, p):
                return 'D'
            return 'C'

    if opp_last == 'C' and n >= 8:
        if opp_c_total * 100 < 85 * n and opp_c_10 < 8:
            if hard <= soft:
                if opp_c_total * 100 < 30 * n:
                    p = 0.92
                elif opp_c_total * 100 < 50 * n:
                    p = 0.80
                elif opp_c_total * 100 < 70 * n:
                    p = 0.62
                else:
                    p = 0.48
            elif hard <= soft + 2:
                p = 0.30
            else:
                p = 0.10
            if opp_c_5 >= 4:
                p -= 0.20
            if recent_my_d >= 4:
                p -= 0.20
            if p > 0 and rng.random() < min(0.92, p):
                return 'D'
            return 'C'

    if opp_last == 'C' and opp_c_total >= n - 2 and hard == 0 and recent_my_d <= 1:
        if n >= 94:
            return 'C'
        if same_count >= 6:
            if n < 60:
                p = 0.010 + 0.020 * (n / 100.0)
            elif n < 75:
                p = 0.030
            else:
                p = 0.060 + 0.160 * ((n - 75) / 25.0)
            if my_last == 'D' and soft == 0:
                p *= 0.35
            if rng.random() < min(0.25, p):
                return 'D'
        return 'C'

    if opp_last == 'C' and same_count >= 5 and n < 92:
        if opp_c_total >= n - 8 and hard == 0:
            p = 0.030
        elif opp_c_total >= n - 16 and hard == 0:
            p = 0.010
        else:
            p = 0.0
        if rng.random() < p:
            return 'D'
        return 'C'

    if opp_last == 'C':
        if my_last == 'D':
            if hard > soft:
                return 'C'
            if soft > hard:
                return 'D'
            if n < 95 and rng.random() < 0.15:
                return 'D'
            return 'C'
        return 'C'

    if n >= 93:
        if same_count >= 6 and opp_c_total >= n - 2 and forgive > 0 and rng.random() < 0.10:
            return 'C'
        return 'D'

    if same_count >= 4:
        if same_count >= 7 and punish >= 3 and forgive == 0:
            return 'D'
        if opp_c_total >= n - 10 and rng.random() < 0.28:
            return 'C'
        if opp_c_total >= n - 25 and rng.random() < 0.12:
            return 'C'
        return 'D'

    if my_last == 'C' and opp_c_total >= n - 3:
        if rng.random() < (0.25 if n >= 85 else 0.45):
            return 'C'
    if opp_c_10 >= 7:
        if rng.random() < (0.18 if n >= 85 else 0.30):
            return 'C'
    if n < 95 and rng.random() < 0.10:
        return 'C'
    return 'D'
